import Uint64 = require( '@stdlib/number/uint64/ctor' );
import isEqual = require( './index' );


// TESTS //

// The function returns a boolean...
{
	const a = new Uint64( 1234 );
	const b = Uint64.of( 0, 1234 );

	isEqual( a, b ); // $ExpectType boolean
}

// The compiler throws an error if the function is provided a first argument which is not a 64-bit unsigned integer...
{
	const b = new Uint64( 1234 );

	isEqual( 'abc', b ); // $ExpectError
	isEqual( 123, b ); // $ExpectError
	isEqual( true, b ); // $ExpectError
	isEqual( false, b ); // $ExpectError
	isEqual( null, b ); // $ExpectError
	isEqual( undefined, b ); // $ExpectError
	isEqual( [], b ); // $ExpectError
	isEqual( {}, b ); // $ExpectError
	isEqual( ( x: number ): number => x, b ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a 64-bit unsigned integer...
{
	const a = new Uint64( 1234 );

	isEqual( a, 'abc' ); // $ExpectError
	isEqual( a, 123 ); // $ExpectError
	isEqual( a, true ); // $ExpectError
	isEqual( a, false ); // $ExpectError
	isEqual( a, null ); // $ExpectError
	isEqual( a, undefined ); // $ExpectError
	isEqual( a, [] ); // $ExpectError
	isEqual( a, {} ); // $ExpectError
	isEqual( a, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const a = new Uint64( 1234 );
	const b = Uint64.of( 0, 1234 );

	isEqual(); // $ExpectError
	isEqual( a ); // $ExpectError
	isEqual( a, b, {} ); // $ExpectError
}

// Attached to the main export is a `words` method which returns a boolean...
{
	isEqual.words( 1, 2, 3, 4 ); // $ExpectType boolean
}

// The compiler throws an error if the `words` method is provided a first argument which is not a number...
{
	isEqual.words( true, 2, 3, 4 ); // $ExpectError
	isEqual.words( false, 2, 3, 4 ); // $ExpectError
	isEqual.words( null, 2, 3, 4 ); // $ExpectError
	isEqual.words( undefined, 2, 3, 4 ); // $ExpectError
	isEqual.words( '5', 2, 3, 4 ); // $ExpectError
	isEqual.words( [], 2, 3, 4 ); // $ExpectError
	isEqual.words( {}, 2, 3, 4 ); // $ExpectError
	isEqual.words( ( x: number ): number => x, 2, 3, 4 ); // $ExpectError
}

// The compiler throws an error if the `words` method is provided a second argument which is not a number...
{
	isEqual.words( 1, true, 3, 4 ); // $ExpectError
	isEqual.words( 1, false, 3, 4 ); // $ExpectError
	isEqual.words( 1, null, 3, 4 ); // $ExpectError
	isEqual.words( 1, undefined, 3, 4 ); // $ExpectError
	isEqual.words( 1, '5', 3, 4 ); // $ExpectError
	isEqual.words( 1, [], 3, 4 ); // $ExpectError
	isEqual.words( 1, {}, 3, 4 ); // $ExpectError
	isEqual.words( 1, ( x: number ): number => x, 3, 4 ); // $ExpectError
}

// The compiler throws an error if the `words` method is provided a third argument which is not a number...
{
	isEqual.words( 1, 2, true, 4 ); // $ExpectError
	isEqual.words( 1, 2, false, 4 ); // $ExpectError
	isEqual.words( 1, 2, null, 4 ); // $ExpectError
	isEqual.words( 1, 2, undefined, 4 ); // $ExpectError
	isEqual.words( 1, 2, '5', 4 ); // $ExpectError
	isEqual.words( 1, 2, [], 4 ); // $ExpectError
	isEqual.words( 1, 2, {}, 4 ); // $ExpectError
	isEqual.words( 1, 2, ( x: number ): number => x, 4 ); // $ExpectError
}

// The compiler throws an error if the `words` method is provided a fourth argument which is not a number...
{
	isEqual.words( 1, 2, 3, true ); // $ExpectError
	isEqual.words( 1, 2, 3, false ); // $ExpectError
	isEqual.words( 1, 2, 3, null ); // $ExpectError
	isEqual.words( 1, 2, 3, undefined ); // $ExpectError
	isEqual.words( 1, 2, 3, '5' ); // $ExpectError
	isEqual.words( 1, 2, 3, [] ); // $ExpectError
	isEqual.words( 1, 2, 3, {} ); // $ExpectError
	isEqual.words( 1, 2, 3, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `words` method is provided an unsupported number of arguments...
{
	isEqual.words(); // $ExpectError
	isEqual.words( 1 ); // $ExpectError
	isEqual.words( 1, 2 ); // $ExpectError
	isEqual.words( 1, 2, 3 ); // $ExpectError
	isEqual.words( 1, 2, 3, 4, 5 ); // $ExpectError
}

// Attached to the main export is a `strided` method which returns a boolean...
{
	const a = new Uint32Array( 2 );
	const b = new Uint32Array( 2 );

	isEqual.strided( a, 1, 0, b, 1, 0 ); // $ExpectType boolean
	isEqual.strided( new Float64Array( 2 ), 1, 0, new Float64Array( 2 ), 1, 0 ); // $ExpectType boolean
	isEqual.strided( [ 0, 0 ], 1, 0, [ 0, 0 ], 1, 0 ); // $ExpectType boolean
}

// The compiler throws an error if the `strided` method is provided a first argument which is not a collection...
{
	const b = new Uint32Array( 2 );

	isEqual.strided( true, 1, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( false, 1, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( null, 1, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( undefined, 1, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( '5', 1, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( [ '5' ], 1, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( {}, 1, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( ( x: number ): number => x, 1, 0, b, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `strided` method is provided a second argument which is not a number...
{
	const a = new Uint32Array( 2 );
	const b = new Uint32Array( 2 );

	isEqual.strided( a, true, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, false, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, null, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, undefined, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, '5', 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, [], 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, {}, 0, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, ( x: number ): number => x, 0, b, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `strided` method is provided a third argument which is not a number...
{
	const a = new Uint32Array( 2 );
	const b = new Uint32Array( 2 );

	isEqual.strided( a, 1, true, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, false, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, null, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, undefined, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, '5', b, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, [], b, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, {}, b, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, ( x: number ): number => x, b, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `strided` method is provided a fourth argument which is not a collection...
{
	const a = new Uint32Array( 2 );

	isEqual.strided( a, 1, 0, true, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, false, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, null, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, undefined, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, '5', 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, [ '5' ], 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, {}, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `strided` method is provided a fifth argument which is not a number...
{
	const a = new Uint32Array( 2 );
	const b = new Uint32Array( 2 );

	isEqual.strided( a, 1, 0, b, true, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, b, false, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, b, null, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, b, undefined, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, b, '5', 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, b, [], 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, b, {}, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, b, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `strided` method is provided a sixth argument which is not a number...
{
	const a = new Uint32Array( 2 );
	const b = new Uint32Array( 2 );

	isEqual.strided( a, 1, 0, b, 1, true ); // $ExpectError
	isEqual.strided( a, 1, 0, b, 1, false ); // $ExpectError
	isEqual.strided( a, 1, 0, b, 1, null ); // $ExpectError
	isEqual.strided( a, 1, 0, b, 1, undefined ); // $ExpectError
	isEqual.strided( a, 1, 0, b, 1, '5' ); // $ExpectError
	isEqual.strided( a, 1, 0, b, 1, [] ); // $ExpectError
	isEqual.strided( a, 1, 0, b, 1, {} ); // $ExpectError
	isEqual.strided( a, 1, 0, b, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `strided` method is provided an unsupported number of arguments...
{
	const a = new Uint32Array( 2 );
	const b = new Uint32Array( 2 );

	isEqual.strided(); // $ExpectError
	isEqual.strided( a ); // $ExpectError
	isEqual.strided( a, 1 ); // $ExpectError
	isEqual.strided( a, 1, 0 ); // $ExpectError
	isEqual.strided( a, 1, 0, b ); // $ExpectError
	isEqual.strided( a, 1, 0, b, 1 ); // $ExpectError
	isEqual.strided( a, 1, 0, b, 1, 0, {} ); // $ExpectError
}
